            cursor: pointer;
            text-align: center;
        }

        .btn-outline-white {
            border: 2px solid white;
            color: white;
            background: transparent;
        }
        .btn-outline-red {
            border: 2px solid var(--primary-red);
            color: var(--primary-red);
            background: transparent;
        }
        .btn-solid-red {
            background: var(--primary-red);
            color: white;
            border: 2px solid var(--primary-red);
